    let max_depth = (2.0 * (len as f64).log2()) as usize;
    introsort(arr, 0, len - 1, max_depth);
}

fn introsort<T: Ord + Clone>(arr: &mut [T], low: usize, high: usize, depth: usize) {
    if high <= low { return; }
    let len = high - low + 1;
    if len <= 24 { insertion_sort(&mut arr[low..=high]); return; }
    if depth == 0 { heapsort(&mut arr[low..=high]); return; }
    let p = partition(arr, low, high);
    if p > 0 { introsort(arr, low, p - 1, depth - 1); }
    introsort(arr, p + 1, high, depth - 1);
}

fn partition<T: Ord + Clone>(arr: &mut [T], low: usize, high: usize) -> usize {
    let mid = low + (high - low) / 2;
    // Median-of-three pivot
    if arr[mid] < arr[low] { arr.swap(low, mid); }
    if arr[high] < arr[low] { arr.swap(low, high); }
    if arr[mid] < arr[high] { arr.swap(mid, high); }
    let pivot = arr[high].clone();
